const webhookItem = $input.first()?.json ?? {};
const payload = webhookItem.body ?? webhookItem;

const asString = (value) => String(value ?? '').trim();
const normalizeDigits = (value) => String(value ?? '').replace(/\D/g, '');
const normalizeGenderCode = (value) => {
  const normalized = asString(value).toUpperCase();
  if (normalized === 'M' || normalized === 'MALE') return 'M';
  if (normalized === 'F' || normalized === 'FEMALE') return 'F';
  return '';
};
const normalizeBirthdateYYMMDD = (value) => {
  const digits = normalizeDigits(value);
  return /^\d{6}$/.test(digits) ? digits : '';
};

const userId = Number(payload.user_id || 0);
const callbackUrl = asString(payload.callback_url);
const documentUrl = asString(payload.document_url);
const seekerName = asString(payload.name);
const submittedQcIdRaw = asString(payload.expected_qc_id);
const expectedQcId = normalizeDigits(submittedQcIdRaw);
const expectedBirthdate = normalizeBirthdateYYMMDD(payload.expected_birthdate);
const expectedGender = normalizeGenderCode(payload.expected_gender);

const precheckErrors = [];
if (!Number.isFinite(userId) || userId <= 0) precheckErrors.push('Missing or invalid user_id in webhook payload.');
if (!callbackUrl) precheckErrors.push('Missing callback_url in webhook payload.');
if (!documentUrl) precheckErrors.push('Missing document_url in webhook payload.');
if (!seekerName) precheckErrors.push('Missing seeker name in webhook payload.');
if (!submittedQcIdRaw) precheckErrors.push('Missing expected_qc_id in webhook payload.');

return [
  {
    json: {
      event: asString(payload.event || 'seeker_id_uploaded').toLowerCase(),
      user_id: Number.isFinite(userId) ? userId : 0,
      callback_url: callbackUrl,
      document_url: documentUrl,
      seeker_name: seekerName,
      submitted_qc_id: submittedQcIdRaw,
      expected_qc_id: expectedQcId,
      expected_birthdate: expectedBirthdate,
      expected_gender: expectedGender,
      precheck_errors: precheckErrors,
    },
  },
];

const asString = (value) => String(value ?? '').trim();
const parseJsonSafely = (value, fallback) => {
  if (value && typeof value === 'object') return value;
  if (typeof value !== 'string' || value.trim() === '') return fallback;
  try {
    return JSON.parse(value);
  } catch {
    return fallback;
  }
};

const response = $input.first()?.json ?? {};
const statusCode = Number(response.statusCode ?? response.status ?? 0);
const body = response.body ?? response;
const qrJson = parseJsonSafely(body, []);
const qrEntry = Array.isArray(qrJson) ? qrJson[0] : null;
const qrSymbol = Array.isArray(qrEntry?.symbol) ? qrEntry.symbol[0] : null;

return [
  {
    json: {
      qr_status_code: Number.isFinite(statusCode) ? statusCode : 0,
      qr_body: body,
      qr_payload_raw: asString(qrSymbol?.data) || null,
      qr_symbol_error: asString(qrSymbol?.error) || null,
    },
  },
];

const asString = (value) => String(value ?? '').trim();
const parseJsonSafely = (value, fallback) => {
  if (value && typeof value === 'object') return value;
  if (typeof value !== 'string' || value.trim() === '') return fallback;
  try {
    return JSON.parse(value);
  } catch {
    return fallback;
  }
};

const response = $input.first()?.json ?? {};
const statusCode = Number(response.statusCode ?? response.status ?? 0);
const body = response.body ?? response;
const ocrJson = parseJsonSafely(body, {});
const parsedResults = Array.isArray(ocrJson?.ParsedResults) ? ocrJson.ParsedResults : [];
const parsedText = parsedResults
  .map((result) => asString(result?.ParsedText))
  .filter(Boolean)
  .join('\n')
  .trim();
const errorMessage = Array.isArray(ocrJson?.ErrorMessage)
  ? ocrJson.ErrorMessage.map((item) => asString(item)).filter(Boolean).join(' | ')
  : asString(ocrJson?.ErrorMessage);

return [
  {
    json: {
      ocr_status_code: Number.isFinite(statusCode) ? statusCode : 0,
      ocr_body: body,
      ocr_reference_id: asString(ocrJson?.OCRExitCode || ''),
      ocr_parsed_results: parsedResults,
      ocr_text: parsedText || null,
      ocr_error_message: errorMessage || null,
      ocr_is_erred_on_processing: Boolean(ocrJson?.IsErroredOnProcessing),
    },
  },
];

const data = $input.first()?.json ?? {};

const asString = (value) => String(value ?? '').trim();
const normalizeDigits = (value) => String(value || '').replace(/\D/g, '');
const normalizeGenderCode = (value) => {
  const normalized = asString(value).toUpperCase();
  if (normalized === 'M' || normalized === 'MALE') return 'M';
  if (normalized === 'F' || normalized === 'FEMALE') return 'F';
  return '';
};
const normalizeBirthdateYYMMDD = (value) => {
  const digits = normalizeDigits(value);
  return /^\d{6}$/.test(digits) ? digits : '';
};
const normalizeNameToken = (value) =>
  String(value || '')
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
const isInitialToken = (value) => {
  const cleaned = normalizeNameToken(String(value || '').replace(/\.+$/, ''));
  return /^[a-z]$/.test(cleaned);
};
const extractNameTokens = (value) =>
  String(value || '')
    .split(/[^A-Za-z0-9]+/)
    .map((token) => normalizeNameToken(token))
    .filter(Boolean);
const normalizeTextForCompare = (value) =>
  String(value || '')
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

const parseQrNameFormat = (value) => {
  const raw = asString(value);
  if (!raw) {
    return { isValid: false, error: 'QR payload full name is empty.' };
  }

  const commaIndex = raw.indexOf(',');
  if (commaIndex < 1) {
    return { isValid: false, error: 'QR name must use LAST, FIRST MIDDLE format.' };
  }

  const familyName = asString(raw.slice(0, commaIndex));
  const rightTokens = asString(raw.slice(commaIndex + 1)).split(/\s+/).filter(Boolean);

  if (!familyName || rightTokens.length < 2) {
    return {
      isValid: false,
      error: 'QR name must include full first and given names plus a trailing surname token.',
    };
  }

  const givenTokens = rightTokens.slice(0, -1);
  const trailingTokenRaw = rightTokens[rightTokens.length - 1];
  const hasInitialInGivenTokens = givenTokens.some((token) => isInitialToken(token));

  if (hasInitialInGivenTokens) {
    return {
      isValid: false,
      error:
        'QR name given tokens are invalid. Use full first/given names; only trailing token may be abbreviated (e.g., M.).',
    };
  }

  const trailingTokenNormalized = normalizeNameToken(trailingTokenRaw);

  return {
    isValid: true,
    familyName,
    givenTokens,
    trailingTokenRaw,
    trailingTokenNormalized,
    trailingTokenInitial: trailingTokenNormalized.charAt(0) || '',
    trailingTokenIsInitial: isInitialToken(trailingTokenRaw),
  };
};

const parseQrPayload = (value) => {
  const raw = asString(value);
  if (!raw) return null;

  const parts = raw.split('|').map((part) => asString(part));
  if (parts.length < 4) {
    return {
      isValid: false,
      error: 'QR payload format was not FULLNAME|QCID|BIRTHDATE|GENDER.',
    };
  }

  const [fullName, qcIdRaw, birthdateRaw, genderRaw] = parts;
  const nameFormat = parseQrNameFormat(fullName);
  const qcIdDigits = normalizeDigits(qcIdRaw);
  const birthdate = normalizeBirthdateYYMMDD(birthdateRaw);
  const gender = normalizeGenderCode(genderRaw);

  if (!nameFormat.isValid) {
    return {
      isValid: false,
      error: nameFormat.error,
      nameFormatValid: false,
      nameFormatError: nameFormat.error,
    };
  }

  if (!fullName || !qcIdDigits) {
    return {
      isValid: false,
      error: 'QR payload is missing full name or QC ID.',
      nameFormatValid: true,
    };
  }

  if (!birthdate) {
    return {
      isValid: false,
      error: 'QR payload birthdate must be YYMMDD.',
      nameFormatValid: true,
    };
  }

  if (!gender) {
    return {
      isValid: false,
      error: 'QR payload gender must be M or F.',
      nameFormatValid: true,
    };
  }

  return {
    isValid: true,
    raw,
    fullName,
    qcIdRaw,
    qcIdDigits,
    birthdate,
    gender,
    nameFormatValid: true,
    nameInfo: nameFormat,
  };
};

const buildOverlayLines = (parsedResults) =>
  parsedResults.flatMap((result) => {
    const lines = Array.isArray(result?.TextOverlay?.Lines) ? result.TextOverlay.Lines : [];
    return lines
      .map((line) => {
        const words = Array.isArray(line?.Words) ? line.Words : [];
        const text = asString(words.map((word) => word?.WordText ?? '').join(' '));
        const topValues = words.map((word) => Number(word?.Top)).filter(Number.isFinite);
        const top = topValues.length > 0 ? Math.min(...topValues) : Number(line?.MinTop);
        return {
          text,
          top: Number.isFinite(top) ? top : null,
        };
      })
      .filter((line) => line.text);
  });

const extractQcIdCandidatesFromText = (text) => {
  const rawText = String(text || '');
  const matches = [
    ...rawText.matchAll(/\b\d{3}[\s-]*\d{3}[\s-]*\d{8}\b/g),
    ...rawText.matchAll(/\b\d{14}\b/g),
  ].map((match) => match[0]);

  return Array.from(new Set(matches.map((value) => asString(value)).filter(Boolean)))
    .map((raw) => ({
      raw,
      digits: normalizeDigits(raw),
      has338Format: /\d{3}[\s-]*\d{3}[\s-]*\d{8}/.test(raw),
    }))
    .filter((candidate) => candidate.digits.length === 14);
};

const rankQcIdCandidates = (parsedText, overlayLines, expectedQcId) => {
  const maxTop = Math.max(1, ...overlayLines.map((line) => line.top).filter(Number.isFinite));
  const byDigits = new Map();

  const scoreCandidate = (candidate) => {
    let score = 0;
    if (expectedQcId.length === 14 && candidate.digits === expectedQcId) score += 100;
    if (candidate.has338Format) score += 20;
    if (candidate.lowerSection) score += 10;
    if (candidate.source === 'overlay') score += 5;
    return score;
  };

  const rememberCandidate = (candidate, sourceText, top, source) => {
    const normalizedCandidate = {
      ...candidate,
      sourceText: sourceText || candidate.raw,
      source,
      top: Number.isFinite(top) ? top : null,
      lowerSection: Number.isFinite(top) ? top >= maxTop * 0.45 : false,
    };
    const existing = byDigits.get(normalizedCandidate.digits);

    if (!existing || scoreCandidate(normalizedCandidate) > scoreCandidate(existing)) {
      byDigits.set(normalizedCandidate.digits, normalizedCandidate);
    }
  };

  overlayLines.forEach((line) => {
    extractQcIdCandidatesFromText(line.text).forEach((candidate) => {
      rememberCandidate(candidate, line.text, line.top, 'overlay');
    });
  });

  extractQcIdCandidatesFromText(parsedText).forEach((candidate) => {
    rememberCandidate(candidate, candidate.raw, null, 'full_text');
  });

  const candidates = Array.from(byDigits.values()).sort((left, right) => scoreCandidate(right) - scoreCandidate(left));
  return { candidates, selected: candidates[0] || null };
};

const event = asString(data.event).toLowerCase();
const userId = Number(data.user_id || 0);
const callbackUrl = asString(data.callback_url);
const seekerName = asString(data.seeker_name);
const submittedQcIdRaw = asString(data.submitted_qc_id);
const expectedQcId = normalizeDigits(data.expected_qc_id || submittedQcIdRaw);
const expectedBirthdate = normalizeBirthdateYYMMDD(data.expected_birthdate);
const expectedGender = normalizeGenderCode(data.expected_gender);
const precheckErrors = Array.isArray(data.precheck_errors) ? data.precheck_errors.filter(Boolean) : [];

if (event && event !== 'seeker_id_uploaded') {
  return [
    {
      json: {
        user_id: Number.isFinite(userId) && userId > 0 ? userId : null,
        callback_url: callbackUrl,
        status: 'skipped',
        reason: 'Unsupported event: ' + event,
        confidence: 0,
        provider: 'ocr.space',
      },
    },
  ];
}

const qrStatusCode = Number(data.qr_status_code || 0);
const ocrStatusCode = Number(data.ocr_status_code || 0);

const qrScan = {
  attempted: true,
  provider: 'api.qrserver.com',
  payload_raw: asString(data.qr_payload_raw) || null,
  full_name: null,
  name_info: null,
  name_format_valid: null,
  name_format_error: null,
  qc_id_raw: null,
  qc_id_digits: null,
  birthdate: null,
  gender: null,
  error: asString(data.qr_symbol_error) || null,
};

const qrPayload = parseQrPayload(qrScan.payload_raw);
if (qrPayload?.isValid) {
  qrScan.full_name = qrPayload.fullName;
  qrScan.name_info = qrPayload.nameInfo || null;
  qrScan.name_format_valid = true;
  qrScan.name_format_error = null;
  qrScan.qc_id_raw = qrPayload.qcIdRaw;
  qrScan.qc_id_digits = qrPayload.qcIdDigits;
  qrScan.birthdate = qrPayload.birthdate;
  qrScan.gender = qrPayload.gender;
  qrScan.error = null;
} else if (qrPayload) {
  qrScan.name_format_valid = qrPayload.nameFormatValid ?? false;
  qrScan.name_format_error = qrPayload.nameFormatError || qrPayload.error || null;
  qrScan.error = qrPayload.error || qrScan.error;
} else if (qrScan.payload_raw && !qrScan.error) {
  qrScan.error = 'QR payload format was not FULLNAME|QCID|BIRTHDATE|GENDER.';
}

const parsedResults = Array.isArray(data.ocr_parsed_results) ? data.ocr_parsed_results : [];
let parsedText = asString(data.ocr_text);
if (!parsedText && parsedResults.length > 0) {
  parsedText = parsedResults
    .map((result) => asString(result?.ParsedText))
    .filter(Boolean)
    .join('\n')
    .trim();
}

const overlayLines = buildOverlayLines(parsedResults);
const normalizedText = normalizeTextForCompare(parsedText);
const normalizedExpectedName = normalizeTextForCompare(seekerName);
const expectedNameTokens = extractNameTokens(seekerName).filter((token) => token.length >= 2);
const requiredNameTokens =
  expectedNameTokens.length >= 2
    ? Array.from(new Set([expectedNameTokens[0], expectedNameTokens[expectedNameTokens.length - 1]]))
    : expectedNameTokens;

const exactOcrNameMatched = normalizedExpectedName.length > 0 && normalizedText.includes(normalizedExpectedName);
const tokenOcrNameMatched =
  requiredNameTokens.length > 0 && requiredNameTokens.every((token) => normalizedText.includes(token));
const ocrNameMatched = exactOcrNameMatched || tokenOcrNameMatched;

const qrNameTokens = extractNameTokens(qrScan.full_name || '');
const qrTokenSet = new Set(qrNameTokens);
const qrCoreTokensMatched =
  requiredNameTokens.length > 0 && requiredNameTokens.every((token) => qrTokenSet.has(token));

let qrTrailingTokenEquivalent = true;
if (qrScan.name_info?.trailingTokenIsInitial && qrScan.name_info.trailingTokenInitial) {
  const trailingMatchesAnyExpected = expectedNameTokens.some(
    (token) => token.length >= 2 && token.startsWith(qrScan.name_info.trailingTokenInitial),
  );
  qrTrailingTokenEquivalent = trailingMatchesAnyExpected || expectedNameTokens.length < 3;
}

const qrNameMatched =
  normalizedExpectedName.length > 0 &&
  qrNameTokens.length > 0 &&
  qrCoreTokensMatched &&
  qrTrailingTokenEquivalent &&
  qrScan.name_format_valid !== false;

const nameMatched = qrScan.full_name ? qrNameMatched : ocrNameMatched;
const titleMatched =
  normalizedText.includes('citizen card') && normalizedText.includes('kasama sa pag unlad');

const { candidates: ocrQcIdCandidates, selected: selectedOcrQcCandidate } = rankQcIdCandidates(
  parsedText,
  overlayLines,
  expectedQcId,
);
const ocrExtractedQcId = selectedOcrQcCandidate?.digits || '';
const ocrIdFormatMatched = ocrQcIdCandidates.some(
  (candidate) => candidate.has338Format && candidate.digits.length === 14,
);
const ocrIdMatched = expectedQcId.length === 14 && ocrQcIdCandidates.some((candidate) => candidate.digits === expectedQcId);

const qrIdFormatMatched = Boolean(qrScan.qc_id_digits) && qrScan.qc_id_digits.length === 14;
const qrIdMatched = expectedQcId.length === 14 && qrScan.qc_id_digits === expectedQcId;

const extractedQcId = qrScan.qc_id_digits || ocrExtractedQcId;
const selectedQcIdSource = qrScan.qc_id_digits ? 'qr_secure' : selectedOcrQcCandidate ? 'ocr' : null;
const idFormatMatched = qrScan.qc_id_digits ? qrIdFormatMatched : ocrIdFormatMatched;
const idMatched = qrScan.qc_id_digits ? qrIdMatched : ocrIdMatched;
const selectedQcIdLine = qrScan.payload_raw || selectedOcrQcCandidate?.sourceText || null;

const detectedQcIdCandidates = Array.from(
  new Set([
    ...(qrScan.qc_id_raw ? [qrScan.qc_id_raw] : []),
    ...ocrQcIdCandidates.map((candidate) => candidate.raw),
  ]),
);

const extractedBirthdate = qrScan.birthdate || null;
const extractedGender = qrScan.gender || null;
const birthdateMatchesProfile =
  expectedBirthdate && extractedBirthdate
    ? expectedBirthdate === normalizeBirthdateYYMMDD(extractedBirthdate)
    : null;
const genderMatchesProfile =
  expectedGender && extractedGender
    ? expectedGender === normalizeGenderCode(extractedGender)
    : null;

const qualificationChecks = {
  citizen_card_title: titleMatched,
  qr_payload_decoded: Boolean(qrScan.full_name && qrScan.qc_id_digits),
  qr_name_format_valid: qrScan.name_format_valid !== false,
  qr_name_matches_submitted: qrNameMatched,
  qr_trailing_token_equivalent: qrTrailingTokenEquivalent,
  cardholder_name: nameMatched,
  qc_id_has_14_digits: idFormatMatched,
  qc_id_format_3_3_8: idFormatMatched,
  qc_id_matches_submitted: idMatched,
  qc_id_found_lower_section: qrScan.qc_id_digits ? true : selectedOcrQcCandidate?.lowerSection || false,
  birthdate_matches_profile: birthdateMatchesProfile,
  gender_matches_profile: genderMatchesProfile,
  qcid_source: selectedQcIdSource,
};

const denialReasons = [...precheckErrors];
const warningMessages = [];

if (qrStatusCode && (qrStatusCode < 200 || qrStatusCode >= 300)) {
  denialReasons.push('QR scanner request failed with HTTP ' + qrStatusCode + '.');
}

if (ocrStatusCode && (ocrStatusCode < 200 || ocrStatusCode >= 300)) {
  denialReasons.push('OCR provider request failed with HTTP ' + ocrStatusCode + '.');
}

if (asString(data.ocr_error_message)) {
  denialReasons.push('OCR provider reported an error: ' + asString(data.ocr_error_message));
}

if (!parsedText) {
  denialReasons.push('OCR could not read any text from the uploaded ID. Please upload a clearer image or PDF.');
}

if (!titleMatched) {
  denialReasons.push('The uploaded ID must show both "Citizen Card" and "Kasama sa pag-unlad".');
}

if (qrScan.payload_raw && qrScan.name_format_valid === false) {
  denialReasons.push('QR name format is invalid. Use LAST, FIRST FULL_GIVEN FULL_OR_INITIAL_TRAILING (e.g., SOLITO, JEFLYN JOY MARAGGUN or SOLITO, JEFLYN JOY M.).');
}

if (normalizedExpectedName.length === 0) {
  denialReasons.push('The submitted seeker name is missing, so name matching could not be completed.');
} else if (!nameMatched) {
  denialReasons.push('The name on the uploaded ID does not match the registered seeker name (' + seekerName + ').');
}

if (expectedQcId.length === 0) {
  denialReasons.push('The submitted QC ID number is missing, so ID matching could not be completed.');
} else if (expectedQcId.length !== 14) {
  denialReasons.push('The submitted QC ID must be 14 digits in 3-3-8 format (example: 078 512 57856458).');
} else if (!idFormatMatched) {
  denialReasons.push('The uploaded card does not show a 14-digit QC ID in the 3-3-8 format (example: 078 512 57856458).');
} else if (!idMatched) {
  denialReasons.push('The QC ID number on the uploaded card does not match the submitted QC ID (' + submittedQcIdRaw + ').');
}

if (expectedBirthdate && extractedBirthdate && birthdateMatchesProfile === false) {
  warningMessages.push('Birthdate from QR does not match the profile birthdate.');
}

if (expectedGender && extractedGender && genderMatchesProfile === false) {
  warningMessages.push('Gender from QR does not match the profile gender.');
}

const status = denialReasons.length === 0 ? 'verified' : 'rejected';
const warningSuffix = warningMessages.length > 0 ? ' Warning: ' + warningMessages.join(' ') : '';
const reason =
  denialReasons.length === 0
    ? 'Verified: Citizen Card title, cardholder name, and 14-digit QC ID all matched' +
      (selectedQcIdSource === 'qr_secure' ? ' using the QR payload.' : ' using OCR fallback.') +
      warningSuffix
    : denialReasons.join(' ') + warningSuffix;

const warningPenalty = warningMessages.length * 0.03;
const confidence =
  denialReasons.length === 0
    ? Math.max(0.82, 0.98 - warningPenalty)
    : Math.max(0.2, 0.92 - denialReasons.length * 0.18 - warningPenalty);

return [
  {
    json: {
      user_id: Number.isFinite(userId) && userId > 0 ? userId : null,
      callback_url: callbackUrl,
      status,
      reason,
      confidence,
      provider: 'ocr.space',
      reference_id: asString(data.ocr_reference_id) || (ocrStatusCode ? String(ocrStatusCode) : null),
      submitted_qc_id: submittedQcIdRaw || null,
      extracted_qc_id: extractedQcId || null,
      extracted_name: nameMatched ? (qrScan.full_name || seekerName) : null,
      extracted_birthdate: extractedBirthdate,
      extracted_gender: extractedGender,
      birthdate_matches_profile: birthdateMatchesProfile,
      gender_matches_profile: genderMatchesProfile,
      warning_messages: warningMessages,
      ocr_text: parsedText || null,
      detected_qc_id_candidates: detectedQcIdCandidates,
      ocr_qc_id_candidates: ocrQcIdCandidates.map((candidate) => candidate.raw),
      qualification_checks: qualificationChecks,
      selected_qc_id_line: selectedQcIdLine,
      selected_qc_id_source: selectedQcIdSource,
      qr_scan: qrScan,
    },
  },
];

const response = $input.first()?.json ?? {};
const statusCode = Number(response.statusCode ?? response.status ?? 0);

return [
  {
    json: {
      callback_status_code: Number.isFinite(statusCode) ? statusCode : 0,
      callback_response_body: response.body ?? null,
      callback_response_headers: response.headers ?? null,
    },
  },
];

const item = $input.first()?.json || {};
const checks = item.qualification_checks || {};
const qrScan = item.qr_scan || {};

return [
  {
    json: {
      _debug_extraction_report: {
        user_id: item.user_id,
        status: item.status,
        confidence_score: item.confidence,
        submitted_qc_id: item.submitted_qc_id || '(not provided)',
        qualification_rules: {
          required_title: 'Citizen Card + Kasama sa pag-unlad',
          required_name_match: true,
          required_qc_id_format: '14 digits in 3-3-8 format',
          preferred_qcid_source: 'QR payload FULLNAME|QCID|BIRTHDATE|GENDER',
        },
        qualification_checks: {
          citizen_card_title: checks.citizen_card_title || false,
          qr_payload_decoded: checks.qr_payload_decoded || false,
          qr_name_matches_submitted: checks.qr_name_matches_submitted || false,
          cardholder_name: checks.cardholder_name || false,
          qc_id_has_14_digits: checks.qc_id_has_14_digits || false,
          qc_id_format_3_3_8: checks.qc_id_format_3_3_8 || false,
          qc_id_matches_submitted: checks.qc_id_matches_submitted || false,
          qc_id_found_lower_section: checks.qc_id_found_lower_section || false,
          qcid_source: checks.qcid_source || '(none)',
        },
        qr_scan: {
          provider: qrScan.provider || '(not attempted)',
          payload_raw: qrScan.payload_raw || '(not found)',
